import json
for f in ['claims.json','valuation_gap.json']:
    d=json.load(open(f)); print(f,'OK')
c=json.load(open('claims.json'))
req={'claim','theory','direct_or_derivative','survives_waiver','limitations','strength','remedy'}
for i,x in enumerate(c):
    assert req<=set(x), (i,set(x))
    assert set(x['limitations'])=={'accrual','barred_portion','tolling_argument'}
    assert isinstance(x['limitations']['barred_portion'],(int,float))
    assert x['theory'] in {'fiduciary','implied_covenant','express_contract','other'}
    assert x['strength'] in {'low','medium','high'} or isinstance(x['strength'],str)
print('claims.json schema OK,', len(c), 'claims')
v=json.load(open('valuation_gap.json'))
assert set(v)=={'book_value_offer','independent_indication_18pct','independent_indication_6_1pct','dilution_valid','why'}
print('valuation_gap.json schema OK')
"

